css:
.ui-card-stage,
.ui-card-stage *,
.ui-card-stage *::before,
.ui-card-stage *::after {
  box-sizing: border-box;
}

.ui-card-stage {
  position: relative;
  width: 240px;
  height: 340px;
  display: grid;
  place-items: center;
  perspective: 1200px;
  transform-style: preserve-3d;
  background: transparent;
}

/* invisible mouse zones */
.hover-zone {
  position: absolute;
  z-index: 30;
}

.zone-left {
  left: 0;
  top: 20%;
  width: 38%;
  height: 60%;
}

.zone-right {
  right: 0;
  top: 20%;
  width: 38%;
  height: 60%;
}

.zone-top {
  top: 0;
  left: 20%;
  width: 60%;
  height: 38%;
}

.zone-bottom {
  bottom: 0;
  left: 20%;
  width: 60%;
  height: 38%;
}

/* main card */
.illustrator-card {
  width: 182px;
  aspect-ratio: 148 / 210;
  position: relative;
  padding: 7px;
  border-radius: 10px;
  overflow: hidden;
  transform-style: preserve-3d;
  transform: rotateX(0deg) rotateY(0deg) translateZ(0);

  background: linear-gradient(
    90deg,
    #6f4205 0%,
    #9b5f09 4%,
    #c98210 10%,
    #f0bd2e 18%,
    #ffe778 28%,
    #fff7bd 37%,
    #d89412 49%,
    #fff5a8 58%,
    #ffe36c 71%,
    #cf8413 84%,
    #8b5608 100%
  );

  box-shadow:
    0 4px 0 #714608,
    0 9px 0 #5b3406,
    0 16px 20px rgba(0, 0, 0, 0.24),
    0 30px 40px rgba(0, 0, 0, 0.18),
    inset 0 2px 0 rgba(255, 255, 255, 0.82),
    inset 0 -7px 14px rgba(83, 42, 0, 0.42),
    inset 0 0 20px rgba(255, 229, 125, 0.18);

  transition:
    transform 0.32s ease,
    box-shadow 0.32s ease,
    filter 0.32s ease;
  filter: saturate(1.05) brightness(1.02);
}

/* outer glow */
.illustrator-card::before {
  content: "";
  position: absolute;
  inset: -8px;
  border-radius: 14px;
  background: radial-gradient(
    circle at center,
    rgba(255, 224, 109, 0.22),
    transparent 70%
  );
  filter: blur(8px);
  z-index: 0;
  pointer-events: none;
}

/* inner border */
.illustrator-card::after {
  content: "";
  position: absolute;
  inset: 10px;
  border: 2px solid #1f1f1f;
  border-radius: 4px;
  box-shadow:
    inset 0 0 0 1px rgba(255, 232, 145, 0.28),
    0 0 0 1px rgba(0, 0, 0, 0.14);
  pointer-events: none;
  z-index: 10;
}

/* gold texture */
.gold-texture {
  position: absolute;
  inset: 0;
  background: radial-gradient(
      circle at 16% 14%,
      rgba(255, 255, 255, 0.52) 0 3%,
      transparent 16%
    ),
    radial-gradient(
      circle at 78% 10%,
      rgba(255, 245, 202, 0.28) 0 5%,
      transparent 18%
    ),
    radial-gradient(circle at 50% 100%, rgba(116, 62, 0, 0.16), transparent 50%),
    repeating-linear-gradient(
      90deg,
      rgba(255, 255, 255, 0.09) 0 1px,
      transparent 1px 4px
    ),
    repeating-linear-gradient(
      0deg,
      rgba(82, 42, 0, 0.06) 0 1px,
      transparent 1px 5px
    );
  mix-blend-mode: overlay;
  opacity: 0.95;
  pointer-events: none;
  z-index: 2;
}

/* extra glossy layer */
.illustrator-card .card-gloss,
.illustrator-card .card-gloss-2 {
  pointer-events: none;
}

.illustrator-card .card-gloss {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.26) 0%,
    rgba(255, 255, 255, 0.08) 12%,
    transparent 35%
  );
  z-index: 3;
}

.illustrator-card .card-gloss-2 {
  position: absolute;
  inset: 0;
  background: radial-gradient(
    circle at 20% 0%,
    rgba(255, 255, 255, 0.22),
    transparent 35%
  );
  z-index: 3;
}

/* moving shine */
.card-shine {
  position: absolute;
  top: -10%;
  left: -60%;
  width: 34%;
  height: 125%;
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(255, 255, 255, 0.18) 30%,
    rgba(255, 255, 255, 0.52) 50%,
    rgba(255, 255, 255, 0.18) 70%,
    transparent 100%
  );
  transform: skewX(-18deg) rotate(6deg);
  filter: blur(0.5px);
  animation: shineMove 3.8s ease-in-out infinite;
  z-index: 20;
  pointer-events: none;
}

/* second soft shine */
.card-shine::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(255, 248, 220, 0.4),
    transparent
  );
  transform: translateX(12px);
  filter: blur(6px);
}

/* side hover effect - stronger 3D */
.zone-left:hover ~ .illustrator-card {
  transform: rotateY(-18deg) rotateX(4deg) translateX(-7px) translateZ(12px)
    scale(1.05);
  box-shadow:
    -10px 5px 0 #714608,
    -20px 12px 0 #5b3406,
    20px 24px 28px rgba(0, 0, 0, 0.28),
    0 38px 42px rgba(0, 0, 0, 0.22),
    inset 0 2px 0 rgba(255, 255, 255, 0.88),
    inset 0 -8px 16px rgba(83, 42, 0, 0.45),
    inset 0 0 22px rgba(255, 230, 136, 0.24);
}

.zone-right:hover ~ .illustrator-card {
  transform: rotateY(18deg) rotateX(4deg) translateX(7px) translateZ(12px)
    scale(1.05);
  box-shadow:
    10px 5px 0 #714608,
    20px 12px 0 #5b3406,
    -20px 24px 28px rgba(0, 0, 0, 0.28),
    0 38px 42px rgba(0, 0, 0, 0.22),
    inset 0 2px 0 rgba(255, 255, 255, 0.88),
    inset 0 -8px 16px rgba(83, 42, 0, 0.45),
    inset 0 0 22px rgba(255, 230, 136, 0.24);
}

.zone-top:hover ~ .illustrator-card {
  transform: rotateX(18deg) rotateY(0deg) translateY(-8px) translateZ(14px)
    scale(1.05);
  box-shadow:
    0 10px 0 #714608,
    0 18px 0 #5b3406,
    0 28px 30px rgba(0, 0, 0, 0.28),
    0 38px 42px rgba(0, 0, 0, 0.22),
    inset 0 2px 0 rgba(255, 255, 255, 0.88),
    inset 0 -8px 16px rgba(83, 42, 0, 0.45);
}

.zone-bottom:hover ~ .illustrator-card {
  transform: rotateX(-18deg) rotateY(0deg) translateY(8px) translateZ(14px)
    scale(1.05);
  box-shadow:
    0 3px 0 #714608,
    0 10px 0 #5b3406,
    0 20px 24px rgba(0, 0, 0, 0.26),
    0 32px 38px rgba(0, 0, 0, 0.2),
    inset 0 2px 0 rgba(255, 255, 255, 0.88),
    inset 0 -8px 16px rgba(83, 42, 0, 0.45);
}

/* screw white boxes - more 3D */
.screw {
  position: absolute;
  width: 14px;
  height: 14px;
  background: linear-gradient(145deg, #ffffff 0%, #ececec 65%, #d3d3d3 100%);
  border: 1px solid rgba(0, 0, 0, 0.28);
  border-radius: 3px;
  z-index: 25;
  box-shadow:
    inset 1px 1px 1px rgba(255, 255, 255, 1),
    inset -1px -1px 2px rgba(0, 0, 0, 0.15),
    0 1px 0 rgba(255, 255, 255, 0.7),
    0 2px 3px rgba(0, 0, 0, 0.18);
  transform: translateZ(10px);
}

.screw::before {
  content: "";
  position: absolute;
  width: 8px;
  height: 2px;
  background: linear-gradient(90deg, #8b8b8b, #636363);
  left: 2px;
  top: 5px;
  border-radius: 99px;
  transform: rotate(35deg);
}

.screw::after {
  content: "";
  position: absolute;
  inset: 3px;
  border-radius: 50%;
  border: 1px solid rgba(0, 0, 0, 0.22);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.8);
}

.screw-tl {
  top: 5px;
  left: 5px;
}
.screw-tr {
  top: 5px;
  right: 5px;
}
.screw-bl {
  bottom: 5px;
  left: 5px;
}
.screw-br {
  bottom: 5px;
  right: 5px;
}

/* header - more embossed */
.card-header {
  position: relative;
  z-index: 8;
  height: 25px;
  margin: 0 0 4px;
  padding-left: 12px;
  display: flex;
  align-items: center;
  border-radius: 2px;
  border: 1.5px solid #7c570b;

  background: linear-gradient(
    90deg,
    #9f5e08 0%,
    #f0bd2e 12%,
    #ffe778 26%,
    #fff7c7 44%,
    #df9914 59%,
    #fff4ad 74%,
    #ba7310 100%
  );

  box-shadow:
    inset 0 2px 0 rgba(255, 255, 255, 0.95),
    inset 0 -3px 5px rgba(88, 45, 0, 0.34),
    0 1px 0 rgba(0, 0, 0, 0.18);
}

.card-header span {
  font-family: Arial, Helvetica, sans-serif;
  font-size: 14px;
  font-weight: 900;
  letter-spacing: 1px;
  color: #2b2100;
  text-shadow:
    1px 1px 0 rgba(255, 255, 255, 0.7),
    2px 2px 0 rgba(103, 55, 0, 0.14);
}

.jp-title {
  position: relative;
  z-index: 8;
  font-size: 6.8px;
  font-weight: 700;
  color: #171717;
  margin: 0 0 4px 3px;
}

/* artwork box more depth */
.art-box {
  position: relative;
  z-index: 8;
  height: 102px;
  border: 2px solid #2c2b16;
  outline: 1.5px solid #e7c74f;
  overflow: hidden;
  background: #9cc55b;
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.18),
    inset 0 0 18px rgba(0, 0, 0, 0.14),
    inset 0 8px 12px rgba(255, 255, 255, 0.08),
    0 2px 0 rgba(0, 0, 0, 0.14);
}

.art-bg {
  position: absolute;
  inset: 0;
  background: radial-gradient(
      circle at 16% 70%,
      rgba(255, 213, 50, 0.95) 0 8%,
      transparent 18%
    ),
    radial-gradient(
      circle at 78% 18%,
      rgba(255, 255, 255, 0.85) 0 5%,
      transparent 13%
    ),
    linear-gradient(135deg, #5b8733 0%, #92bc55 38%, #e4ec73 60%, #4b7131 100%);
}

.art-bg::before {
  content: "";
  position: absolute;
  inset: -10px;
  background: repeating-linear-gradient(
    124deg,
    rgba(55, 88, 31, 0.42) 0 8px,
    transparent 8px 18px
  );
}

.art-bg::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.16) 0%,
    transparent 45%
  );
}

.white-swoosh {
  position: absolute;
  right: 20px;
  top: 14px;
  width: 50px;
  height: 42px;
  border-radius: 50%;
  border-top: 4px solid rgba(255, 255, 255, 0.95);
  transform: rotate(20deg);
  filter: drop-shadow(0 0 4px rgba(255, 255, 255, 0.65))
    drop-shadow(0 0 10px rgba(255, 255, 255, 0.22));
}

.white-swoosh::before {
  content: "";
  position: absolute;
  width: 27px;
  height: 18px;
  top: 9px;
  left: 8px;
  border-radius: 50%;
  border-top: 3px solid rgba(255, 255, 255, 0.92);
}

.star {
  position: absolute;
  width: 4px;
  height: 4px;
  background: #fffbd0;
  border-radius: 50%;
  box-shadow:
    0 0 8px #fff,
    0 0 14px rgba(255, 255, 255, 0.42);
  animation: starFlash 1.6s ease-in-out infinite alternate;
}

.star::before,
.star::after {
  content: "";
  position: absolute;
  background: #fffbd0;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
}

.star::before {
  width: 10px;
  height: 1px;
}
.star::after {
  width: 1px;
  height: 10px;
}

.s1 {
  left: 16px;
  top: 17px;
}
.s2 {
  right: 18px;
  top: 25px;
  animation-delay: 0.4s;
}
.s3 {
  left: 28px;
  bottom: 22px;
  animation-delay: 0.8s;
}

/* text area more inset */
.text-box {
  position: relative;
  z-index: 8;
  margin-top: 7px;
  min-height: 82px;
  padding: 7px 6px;
  background: linear-gradient(180deg, #f1f0df 0%, #d6d2bd 100%);
  border: 2px solid #4b4b4b;
  border-radius: 2px;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.84),
    inset 0 -2px 7px rgba(0, 0, 0, 0.12),
    0 1px 0 rgba(255, 255, 255, 0.14);
}

.text-box p {
  margin: 0 0 4px;
  font-family: Arial, Helvetica, sans-serif;
  font-size: 6.2px;
  line-height: 1.42;
  font-weight: 700;
  color: #252525;
}

/* keep your existing Pikachu CSS - if you want, you can use the same one from previous code */

/* animations */
@keyframes shineMove {
  0% {
    left: -60%;
  }
  45% {
    left: 122%;
  }
  100% {
    left: 122%;
  }
}

@keyframes starFlash {
  from {
    transform: scale(0.78);
    opacity: 0.58;
  }
  to {
    transform: scale(1.12);
    opacity: 1;
  }
}
/* Better Pikachu CSS - add this at bottom */
.pika {
  position: absolute;
  width: 88px;
  height: 78px;
  left: 50%;
  top: 57%;
  transform: translate(-50%, -50%) rotate(-10deg);
  animation: pikaFloat 2.8s ease-in-out infinite;
  z-index: 8;
}

.head {
  position: absolute;
  left: 18px;
  top: 8px;
  width: 50px;
  height: 40px;
  background: linear-gradient(180deg, #ffde49 0%, #f2bf24 100%);
  border: 2.2px solid #34250c;
  border-radius: 47% 47% 42% 42%;
  z-index: 5;
  box-shadow:
    inset 6px -6px 0 rgba(196, 136, 11, 0.16),
    inset -3px 3px 0 rgba(255, 255, 255, 0.22),
    0 1px 2px rgba(0, 0, 0, 0.18);
}

.ear {
  position: absolute;
  width: 13px;
  height: 40px;
  background: linear-gradient(to bottom, #251d12 0 27%, #f8cf30 28% 100%);
  border: 2px solid #34250c;
  border-radius: 50% 50% 25% 25%;
  z-index: 2;
}

.ear-left {
  left: 22px;
  top: -8px;
  transform: rotate(-28deg);
}

.ear-right {
  left: 52px;
  top: -6px;
  transform: rotate(28deg);
}

.eye {
  position: absolute;
  width: 6px;
  height: 7px;
  background: #151515;
  border-radius: 50%;
  top: 14px;
}

.eye::after {
  content: "";
  position: absolute;
  width: 2px;
  height: 2px;
  top: 1px;
  left: 1px;
  background: #fff;
  border-radius: 50%;
}

.eye-left {
  left: 11px;
}

.eye-right {
  right: 11px;
}

.cheek {
  position: absolute;
  width: 9px;
  height: 8px;
  background: #e84a34;
  border-radius: 50%;
  top: 24px;
  box-shadow: inset 1px 1px 0 rgba(255, 255, 255, 0.25);
}

.cheek-left {
  left: 3px;
}

.cheek-right {
  right: 3px;
}

.nose {
  position: absolute;
  left: 23px;
  top: 20px;
  width: 4px;
  height: 3px;
  background: #2b1b08;
  border-radius: 50%;
}

.mouth {
  position: absolute;
  left: 20px;
  top: 24px;
  width: 10px;
  height: 5px;
  border-bottom: 2px solid #2b1b08;
  border-radius: 0 0 50% 50%;
}

.body {
  position: absolute;
  left: 26px;
  top: 37px;
  width: 36px;
  height: 29px;
  background: linear-gradient(180deg, #ffd83f 0%, #e7ad1d 100%);
  border: 2px solid #34250c;
  border-radius: 50% 50% 42% 42%;
  z-index: 4;
  box-shadow:
    inset 5px -5px 0 rgba(174, 112, 8, 0.15),
    inset -2px 2px 0 rgba(255, 255, 255, 0.18);
}

.arm {
  position: absolute;
  width: 12px;
  height: 18px;
  background: #efbe24;
  border: 2px solid #34250c;
  border-radius: 50%;
  z-index: 6;
}

.arm-left {
  left: 21px;
  top: 39px;
  transform: rotate(25deg);
}

.arm-right {
  left: 55px;
  top: 37px;
  transform: rotate(-35deg);
}

.foot {
  position: absolute;
  width: 13px;
  height: 8px;
  background: #df9e14;
  border: 2px solid #34250c;
  border-radius: 50%;
  z-index: 3;
}

.foot-left {
  left: 26px;
  top: 64px;
  transform: rotate(12deg);
}

.foot-right {
  left: 46px;
  top: 64px;
  transform: rotate(-12deg);
}

.tail {
  position: absolute;
  right: -1px;
  top: 24px;
  width: 33px;
  height: 43px;
  background: linear-gradient(180deg, #ffd53c, #edb21f);
  border: 2px solid #34250c;
  clip-path: polygon(
    0 45%,
    35% 45%,
    28% 18%,
    63% 18%,
    54% 0,
    100% 32%,
    70% 32%,
    78% 66%,
    38% 66%,
    45% 100%,
    15% 100%,
    7% 70%,
    0 70%
  );
  z-index: 1;
}

.pencil {
  position: absolute;
  left: 7px;
  top: 47px;
  width: 51px;
  height: 7px;
  border: 1.6px solid #34250c;
  border-radius: 8px;
  background: linear-gradient(
    90deg,
    #c64a34 0 66%,
    #f2cf8b 66% 86%,
    #1d1d1d 86% 100%
  );
  transform: rotate(-31deg);
  z-index: 8;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.3),
    0 1px 2px rgba(0, 0, 0, 0.22);
}

@keyframes pikaFloat {
  0%,
  100% {
    transform: translate(-50%, -50%) rotate(-10deg);
  }
  50% {
    transform: translate(-50%, -54%) rotate(-7deg);
  }
}
